/* Speculative Score Draft for Tone.js */

// Set global tempo and a master reverb.
Tone.Transport.bpm.value = 133;
const reverb = new Tone.Reverb({ decay: 8, wet: 1 }).toDestination();

// 1. Epic Lead Synth
const leadSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 5, spread: 30 },
  envelope: { attack: 0.05, decay: 0.4, sustain: 0.7, release: 1.5 },
  filter: { type: 'lowpass', frequency: 4000, Q: 2.5 },
  volume: -9
});
const leadFx = new Tone.Chorus(0.4, 2.5, 1).connect(reverb);
leadSynth.chain(new Tone.Distortion(0.2), leadFx);
// Example pattern:
const leadPattern = new Tone.Sequence((time, note) => {
  leadSynth.triggerAttackRelease(note, '8n', time);
}, ['B4', null, 'D5', null, 'E5', 'G5', 'A5', 'G5', 'B5', 'A5', 'G5', 'E5', 'D5', null, 'B4', null], '16n');

// 2. Synth Orchestra Pad
const padSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 7, spread: 40 },
  envelope: { attack: 1.5, decay: 0.5, sustain: 1, release: 4 },
  filter: { type: 'lowpass', frequency: 2200, Q: 1.5 },
  volume: -15
});
const padFx = new Tone.Chorus(0.7, 2.5, 1).connect(reverb);
padSynth.chain(new Tone.Distortion(0.1), padFx);
// Example pattern (progression would be handled by multiple patterns or a part):
const padPattern = new Tone.Part((time, value) => {
  padSynth.triggerAttackRelease(value.notes, value.duration, time);
}, [
  { time: '0:0', notes: ['E3','G3','B3','D4'], duration: '2m' },
  { time: '2:0', notes: ['C3','E3','G3','B3'], duration: '2m' }
]);
